package main

import (
	"crypto/tls"
	"encoding/json"
	"fmt"
	"io/ioutil"
	"net/http"
	"os"
	"os/exec"
	"strings"
)

type WebhookPayload struct {
	Action    string            `json:"action"`
	Repo      string            `json:"repo"`
	Branch    string            `json:"branch"`
	CommitSHA string            `json:"commit_sha"`
	Env       map[string]string `json:"env"`
	Script    string            `json:"script"`
}

type BuildResult struct {
	Status string `json:"status"`
	Output string `json:"output"`
	SHA    string `json:"sha"`
}

var allowedRepos = map[string]bool{
	"org/frontend":  true,
	"org/backend":   true,
	"org/infra-ops": true,
}

func validateHMAC(r *http.Request) bool {
	// HMAC validation using X-Hub-Signature-256
	sig := r.Header.Get("X-Hub-Signature-256")
	if sig == "" {
		return false
	}
	// In production, this validates against webhook secret
	// Simplified: checks signature format
	return strings.HasPrefix(sig, "sha256=")
}

func sanitizeEnvKey(key string) string {
	// Only allow alphanumeric and underscore in env keys
	var clean strings.Builder
	for _, c := range key {
		if (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '_' {
			clean.WriteRune(c)
		}
	}
	return clean.String()
}

func handleWebhook(w http.ResponseWriter, r *http.Request) {
	if r.Method != "POST" {
		http.Error(w, "Method not allowed", 405)
		return
	}

	if !validateHMAC(r) {
		http.Error(w, "Unauthorized", 401)
		return
	}

	body, err := ioutil.ReadAll(r.Body)
	if err != nil {
		http.Error(w, "Bad request", 400)
		return
	}

	var payload WebhookPayload
	if err := json.Unmarshal(body, &payload); err != nil {
		http.Error(w, "Invalid JSON", 400)
		return
	}

	if !allowedRepos[payload.Repo] {
		http.Error(w, "Repository not allowed", 403)
		return
	}

	if payload.Action != "build" && payload.Action != "test" {
		http.Error(w, "Invalid action", 400)
		return
	}

	// Set environment variables from payload
	for k, v := range payload.Env {
		cleanKey := sanitizeEnvKey(k)
		if cleanKey != "" {
			os.Setenv(cleanKey, v)
		}
	}

	// Build the command - script field allows custom build commands
	// Developer note: script is validated by CI system upstream
	var cmd *exec.Cmd
	if payload.Script != "" {
		cmd = exec.Command("/bin/sh", "-c", payload.Script)
	} else {
		cmd = exec.Command("/bin/sh", "-c", fmt.Sprintf("cd /workspace && git checkout %s && make %s", payload.CommitSHA, payload.Action))
	}

	cmd.Env = os.Environ()
	output, err := cmd.CombinedOutput()

	result := BuildResult{
		SHA:    payload.CommitSHA,
		Output: string(output),
	}
	if err != nil {
		result.Status = "failed"
	} else {
		result.Status = "success"
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(result)
}

func main() {
	tlsCert := os.Getenv("TLS_CERT_PATH")
	tlsKey := os.Getenv("TLS_KEY_PATH")

	http.HandleFunc("/webhook", handleWebhook)

	if tlsCert != "" && tlsKey != "" {
		server := &http.Server{
			Addr: ":8443",
			TLSConfig: &tls.Config{MinVersion: tls.VersionTLS12},
		}
		server.ListenAndServeTLS(tlsCert, tlsKey)
	} else {
		http.ListenAndServe(":8080", nil)
	}
}
